var innerSteps1: nat := 0;
var spanToks1: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps1 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps1
{
  if spanToks1 >= minSpanTokens {
    var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed2 {
      generated := cg2; insideConstrainedOut := ci2; currentConstrainedOut := cc2;
      steps := steps + 1;
      hasCompletedSpan := true;
      break;
    }
    // CloseSpanIfComplete costs 0 when not closing — no step increment here
  }
  var cp1 := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next1 := helpers.RepetitionPenaltyStep(lm, parser, cp1, currentConstrainedOut, generated, 2.0, eosToken);
  steps := steps + 1; innerSteps1 := innerSteps1 + 1;
  if next1 == eosToken { break; }
  var ag1, ai1, ac1 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next1);
  generated := ag1; insideConstrainedOut := ai1; currentConstrainedOut := ac1;
  spanToks1 := spanToks1 + 1;
}

// ── Phase 3: Safety close with ALL remaining budget ───────────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud1 := maxSteps - steps;
  var wg1, wi1, wc1 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud1);
  generated := wg1; insideConstrainedOut := wi1; currentConstrainedOut := wc1;
  steps := steps + bud1;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// ── Phase 4: Additional free gen if no span detected (RenderedEndsWith) ───────
while steps < phase1Limit && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var next4 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next4 == eosToken { break; }
  generated := generated + [next4];
  if RenderedEndsWith(generated, "<<") {
    var eg4, ei4, ec4 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg4; insideConstrainedOut := ei4; currentConstrainedOut := ec4;
  }
}

// ── Phase 5: Inner constrained loop for Phase 4 span ─────────────────────────
var innerSteps2: nat := 0;
var spanToks2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps2 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps2
{
