    generated := wg3; insideConstrainedOut := wi3; currentConstrainedOut := wc3;
    steps := steps + bud3;
  }
}

// ── Phase 8: Final safety close with all remaining budget ─────────────────────
if insideConstrainedOut && steps < maxSteps {
  var bud4 := maxSteps - steps;
  if bud4 > 0 {
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud4);
